# InformationWrapper InformationWrapper Компонент обертка для элементов формы. ## Примеры Примеры ### Базовое использование Базовое использование ```tsx
import React from 'react';
import { InformationWrapper, TextField, TextArea } from '@salutejs/sdds-finai';

export function App() {
    const size = 's';

    const commonProps = {
        label: 'Лейбл',
        titleCaption: 'Подпись к полю',
        leftHelper: 'Подсказка слева',
        rightHelper: 'Подсказка справа',
        hintText: 'Текст тултипа',
    };

    const SvgPlaceholder = () => {
        return (
            <div
                style={{
                    height: '3rem',
                    background:
                        'linear-gradient(to right, #9747FF 0.063rem, transparent 0.063rem) 0 0, linear-gradient(to right, #9747FF 0.063rem, transparent 0.063rem) 0 100%, linear-gradient(to left, #9747FF 0.063rem, transparent 0.063rem) 100% 0, linear-gradient(to left, #9747FF 0.063rem, transparent 0.063rem) 100% 100%, linear-gradient(to bottom, #9747FF 0.063rem, transparent 0.063rem) 0 0, linear-gradient(to bottom, #9747FF 0.063rem, transparent 0.063rem) 100% 0, linear-gradient(to top, #9747FF 0.063rem, transparent 0.063rem) 0 100%, linear-gradient(to top, #9747FF 0.063rem, transparent 0.063rem) 100% 100%',
                    backgroundRepeat: 'no-repeat',
                    backgroundSize: '3rem 1rem',
                }}
            />
        );
    };

    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '2rem', padding: '2rem' }}>
            <InformationWrapper
                {...commonProps}
                size={size}
                hasRequiredIndicator
            >
                <SvgPlaceholder />
            </InformationWrapper>

            <InformationWrapper
                {...commonProps}
                size={size}
                hasRequiredIndicator
                labelHtmlFor="example-id-textfield-for-wrapper"
            >
                <TextField id="example-id-textfield-for-wrapper" size={size} />
            </InformationWrapper>

            <InformationWrapper
                {...commonProps}
                size={size}
                hasRequiredIndicator
                labelHtmlFor="example-id-textarea-for-wrapper"
            >
                <TextArea id="example-id-textarea-for-wrapper" size={size} />
            </InformationWrapper>
        </div>
    );
}
```

